import{Port}from'../../core/index.js';
import{addCadParts}from'../../modeling/cad.js';
import{THREE,materials,mesh,slab,portQuaternion,FACE,solid,hole,ring,ringY,cappedSweep,tau}from'./geometry.js';
import data from'./geometry-data.js';import{spec}from'./dimensions.js';import{Antenna}from'./Antenna.js';import{addStickers}from'./stickers.js';
function board(host){
 const s=new THREE.Shape();s.moveTo(-5.5,-30.2);s.lineTo(-8.7,-30.2);s.lineTo(-10.1,-28.8);s.lineTo(-10.1,-25);s.lineTo(-5.2,-25);s.quadraticCurveTo(-3.7,-23.6,-3.7,-21.5);s.lineTo(-3.7,-19.7);s.quadraticCurveTo(-3.7,-17.7,-5.3,-16.5);s.lineTo(-10.1,-16.5);s.lineTo(-10.1,24.2);s.lineTo(-8.8,25.5);s.lineTo(8.8,25.5);s.lineTo(10.1,24.2);s.lineTo(10.1,-16.5);s.lineTo(5.3,-16.5);s.quadraticCurveTo(3.7,-17.7,3.7,-19.7);s.lineTo(3.7,-21.5);s.quadraticCurveTo(3.7,-23.6,5.2,-25);s.lineTo(10.1,-25);s.lineTo(10.1,-28.8);s.lineTo(8.7,-30.2);s.lineTo(5.5,-30.2);s.lineTo(5.5,-25.3);s.lineTo(-5.5,-25.3);s.closePath();
 const holes=[[0,-20,1.6],...[-3,-1,1,3].map(x=>[x,-24.2,.48])];for(const[x,y,r]of holes)hole(s,x,y,r);
 const green=materials.plastic(0x176c45,{roughness:.9}),tin=materials.metal(0xbec2ad,{roughness:.56}),dark=materials.plastic(0x212722,{roughness:.88}),gold=materials.metal(0xc4ad4d,{roughness:.58}),pcb=solid(host.body,s,.8,[0,0,-1.8],green,'CatM own populated PCB with actual photographed neck/mount reliefs,hidden outline and installation inferred');pcb.userData={role:'physical-pcb',installationInferred:true};
 const pads=[],barrels=[];for(const[x,y,r]of holes.slice(1)){pads.push(ring(host.body,.7,.34,.05,[x,y,-1],tin,'CatM actual Grove plated annular solder pad'));barrels.push(ring(host.body,r,.34,.8,[x,y,-1.8],tin,'CatM actual Grove empty plated solder barrel'));}
 const substrate=slab(host.body,17.6,15.7,.5,.1,[0,-5,-1],green,[],.01);substrate.name='CatM exact SIM7080G documented17.6×15.7 module substrate,concealed placement inferred';const module=slab(host.body,17.25,15.35,1.8,.15,[0,-5,-.5],materials.metal(0xbcc0b5,{roughness:.72}),[],.01);module.name='CatM actual SIM7080G closed shield package envelope,concealed installation inferred';
 const packages=[];function chip(name,x,y,w,h,d,legs=0){const body=slab(host.body,w,h,d,.07,[x,y,-1],dark,[],.005);body.name='CatM actual '+name+' package envelope,placement inferred';const pins=[];for(let side of[-1,1])for(let i=0;i<legs/2;i++)pins.push(mesh(host.body,new THREE.BoxGeometry(.45,.35,.18),tin,[x+side*(w/2+.16),y+(i-(legs/2-1)/2)*.65,-.91],'CatM '+name+' actual solder termination envelope'));const item={body,pins};packages.push(item);return item;}
 chip('U1 SY8003ADFC',-6.7,-14.2,2.9,1.6,1.1,6);chip('U2 SMF05CT1G',7.2,5.4,2,1.25,.85,6);for(const[n,x,y]of[['Q1 SS8050',-8,7],['Q2 SS8050',6.9,-14.3],['Q3 SS8050',8.3,-11.7]]){const q=chip(n,x,y,1.6,2.7,.9);for(const[dx,dy]of[[-1,-.65],[-1,.65],[1,0]])q.pins.push(mesh(host.body,new THREE.BoxGeometry(.5,.35,.18),tin,[x+dx,y+dy,-.91],'CatM actual SS8050 three solder feet'));}
 const inductor=slab(host.body,3,3,1.2,.2,[-2.5,-14.1,-1],materials.plastic(0x545a50),[],.01);inductor.name='CatM actual L1 WPN3012H2R2MT closed inductor envelope';const capacitors=[];for(const[x,y]of[[2,-14.4],[4.7,-14.4],[-7.5,11.1]]){const c=slab(host.body,2,1.25,.8,.06,[x,y,-1],materials.plastic(0xae9b71),[],.005);c.name='CatM documented22uF capacitor envelope,concealed placement inferred';capacitors.push(c);for(const sign of[-1,1])mesh(host.body,new THREE.BoxGeometry(.3,1.25,.15),tin,[x+sign*.88,y,-.925],'CatM actual capacitor termination');}
 const netlight=slab(host.body,1.6,.8,.6,.04,[-7,20.2,-1],materials.plastic(0xe1dcc1,{roughness:.8}),[],.004);netlight.name='CatM D1 actual concealed0603 NETLIGHT package,nonemissive,no external window inferred';netlight.userData={role:'physical-concealed-indicator',emits:false};
 const ipexBase=slab(host.body,2.5,2.5,.4,.1,[-7.1,15.6,-1],dark,[],.005);ipexBase.name='CatM actual E1 IPEX physical receiving carrier';const ipex=ring(host.body,.85,.33,.55,[-7.1,15.6,-.6],gold,'CatM actual E1 IPEX bored coax socket'),ipexPin=mesh(host.body,new THREE.CylinderGeometry(.18,.18,.35,24).rotateX(Math.PI/2),gold,[-7.1,15.6,-.25],'CatM actual IPEX central contact');
 const coaxCurve=new THREE.CatmullRomCurve3([new THREE.Vector3(-7.1,15.6,.3),new THREE.Vector3(-7.1,21.8,.8),new THREE.Vector3(-3.4,24.8,.5),new THREE.Vector3(0,26,.1)]),coax=mesh(host.body,cappedSweep(coaxCurve,.4),materials.plastic(0x1d2b25),[0,0,0],'CatM own photographed single pigtail coax,concealed route inferred');const coaxPlug=slab(host.body,1.8,2.1,.6,.2,[-7.1,15.6,-.05],gold,[],.01);coaxPlug.name='CatM actual retained IPEX pigtail plug envelope';return{pcb,holes,pads,barrels,substrate,module,packages,inductor,capacitors,netlight,ipexBase,ipex,ipexPin,coax,coaxPlug};
}
function simHolder(host){
 const frame=new THREE.Group();frame.name='CatM exact NanoSIM internal receiving structure,no card/no exposed port';frame.position.fromArray(spec.sim.holderCentre);host.body.add(frame);const black=materials.plastic(0x202720,{roughness:.9}),tin=materials.metal(0xb7bfb5,{roughness:.58}),gold=materials.metal(0xc8ad4c),floor=slab(frame,12.8,14.5,.35,.2,[0,0,0],black,[],.01);floor.name='CatM NanoSIM actual closed dielectric floor';const cover=slab(frame,12.6,14.2,.18,.3,[0,0,1.8],tin,[{w:1.8,h:7.1,r:.85,cx:-.7,cy:0},...[-3.3,0,3.3].map(y=>({w:1.2,h:1.2,r:.6,cx:-4,cy:y}))],0);cover.name='CatM NanoSIM actual photographed perforated retention shield';const walls=[];for(const sign of[-1,1])walls.push(mesh(frame,new THREE.BoxGeometry(12.6,.3,1.6),tin,[0,sign*6.95,1.1],'CatM NanoSIM fixed metal side retention wall'));const stop=mesh(frame,new THREE.BoxGeometry(.35,13.6,1.6),black,[-6.175,0,1.1],'CatM NanoSIM actual deep dielectric end stop');const contacts=[];for(const x of[-2.4,2.4])for(const y of[-3.3,0,3.3])contacts.push(mesh(frame,new THREE.BoxGeometry(2,1.1,.18),gold,[x,y,.44],'CatM NanoSIM actual six visible contact spring envelopes,hidden dimensions inferred'));const mouth=mesh(frame,new THREE.BoxGeometry(.35,14.2,.35),tin,[6.175,0,.52],'CatM NanoSIM fixed entry retaining lip,concealed behind intact source shell');return{frame,floor,cover,walls,stop,contacts,mouth,cardIncluded:false,concealed:true};
}
function grove(host){
 const frame=new THREE.Group();frame.name='CatM actual blue HY2.0-4P open receiving socket';frame.position.fromArray(spec.grove.position);frame.quaternion.copy(FACE.bottom);host.body.add(frame);const blue=materials.plastic(spec.grove.color,{roughness:.67}),tin=materials.metal(0xb7bba4),box=(s,p,n,m=blue)=>mesh(frame,new THREE.BoxGeometry(...s),m,p,'CatM Grove '+n),walls=[];for(const sign of[-1,1]){walls.push(box([.65,5.2,6.3],[sign*4.675,0,-3.15],'actual side wall'));box([.7,.6,3.2],[sign*3.85,2.3,-4.7],'actual guide rail');box([.6,.45,1.2],[sign*3.65,2.375,-1.8],'actual latch shoulder');}const floor=box([8.7,.65,6.3],[0,-2.275,-3.15],'actual floor'),rear=box([8.7,4.55,.65],[0,.325,-5.975],'actual closed dielectric back'),bridge=box([4.8,.45,2.3],[0,2.375,-4.5],'actual retaining bridge'),contacts=[],tails=[];for(let i=0;i<4;i++){contacts.push(box([.42,.42,4.5],[(i-1.5)*2,.2,-3.6],'actual recessed contact'+(i+1),tin));const t=new THREE.Group();t.name='CatM Grove actual bent solder tail'+(i+1);frame.add(t);mesh(t,new THREE.BoxGeometry(.42,.42,2),tin,[(i-1.5)*2,.2,-6.7],'CatM Grove actual rearward solder segment');mesh(t,new THREE.BoxGeometry(.42,3.6,.42),tin,[(i-1.5)*2,-1.5,-7.7],'CatM Grove actual plated-through solder leg');tails.push(t);}const port=host.add(new Port({id:'grove',label:'PORT.C UART · physical G/5/R/T labels only',connector:'grove',position:spec.grove.position,quaternion:portQuaternion('bottom'),hitSize:[10,1,5.2],pins:spec.grove.pins.map((name,i)=>({n:i+1,name})),pinGrid:{cols:4,rows:1,pitch:2,center:[0,.2],order:col=>4-col},meta:{role:'visual-connector',face:'bottom',scope:'Four actual contacts and four-core cable attachment only.No UART/AT/network/electrical behavior.'}}));return{frame,walls,floor,rear,bridge,contacts,tails,port};
}
function sma(host){
 const frame=new THREE.Group();frame.name='CatM actual single bulkhead ordinary SMA-female pigtail assembly';host.body.add(frame);const gold=materials.metal(0xc7ad49,{roughness:.43}),white=materials.plastic(0xe8e5cf,{roughness:.83}),base=mesh(frame,new THREE.CylinderGeometry(3.8,3.8,2.5,6),gold,[0,28,0],'CatM actual captured hex nut behind real native front/rear windows'),barrel=ringY(frame,3.05,2.1,8,32,gold,'CatM actual hollow ordinary SMA outer receiving barrel'),rear=ringY(frame,2.5,.65,7.2,24.8,gold,'CatM SMA actual bored rear pigtail carrier'),dielectric=ringY(frame,2.07,.65,1.2,38.4,white,'CatM SMA actual bored dielectric face'),contact=ringY(frame,.63,.32,3.1,36.6,gold,'CatM SMA actual female centre-contact socket'),floor=mesh(frame,new THREE.CylinderGeometry(.32,.32,.12,32),gold,[0,36.54,0],'CatM SMA actual deep blind female contact floor'),threads=[];for(let i=0;i<11;i++)threads.push(mesh(frame,new THREE.TorusGeometry(3.1,.12,8,48).rotateX(Math.PI/2),gold,[0,32.5+i*.65,0],'CatM SMA fixed external thread crest'));const port=host.add(new Port({id:'sma',label:'Ordinary SMA female · physical cellular antenna interface',connector:'sma-female',position:spec.sma.position,hitSize:[7,1,7],meta:{role:'visual-connector',face:'top',physicalConnector:'sma-female',scope:'Single ordinary SMA mechanical attachment only.No RF,cellular,signal,network,gain,electrical behavior.'}}));return{frame,base,barrel,rear,dielectric,contact,floor,threads,port};
}
function fixing(host){const tin=materials.metal(0xb5bcb2,{roughness:.5}),items=[];for(const[x,y]of[[-8,27.5],[8,27.5],[0,-20]]){const s=new THREE.Shape();s.absarc(0,0,1.5,0,tau,false);const h=new THREE.Path();for(let i=0;i<6;i++){const a=-i*tau/6;i?h.lineTo(.6*Math.cos(a),.6*Math.sin(a)):h.moveTo(.6*Math.cos(a),.6*Math.sin(a));}h.closePath();s.holes.push(h);const head=solid(host.body,s,.4,[x,y,-3.98],tin,'CatM actual fixed rear hex retaining screw head'),floor=mesh(host.body,new THREE.CylinderGeometry(.61,.61,.1,6).rotateX(Math.PI/2),tin,[x,y,-3.53],'CatM actual blind retaining hex floor'),shank=mesh(host.body,new THREE.CylinderGeometry(.6,.6,5.2,32).rotateX(Math.PI/2),tin,[x,y,-.9],'CatM actual fixed retaining shank');items.push({head,floor,shank});}return items;}
export function buildCatM(host,{antenna=false}={}){if(typeof antenna!=='boolean')throw new TypeError('antenna must be boolean');const parts=addCadParts(host,data,{shell:materials.plastic(0x555a56,{roughness:.85})}),pcb=board(host),input=grove(host),output=sma(host),sim=simHolder(host),screws=fixing(host),labels={};for(const face of['front','back']){const v=spec.labels[face],p=slab(host.body,...v.size,.04,.8,v.position,materials.plastic(0xd9dcda,{roughness:.89}),[],0);p.name='CatM actual '+face+' adhesive film';p.userData={role:'physical-label-substrate',face};labels[face]=p;}host.catmAssembly={parts,pcb,input,sma:output,sim,screws,labels};host.unitStickers=addStickers(host);if(antenna)output.port.attach(new Antenna());}
